#!/usr/bin/env node
// Real-cost A/B benchmark (SPENDS MONEY): node bench-cost.mjs [--runs 1] [--tasks 5] [--model sonnet] [--budget 0.6] [--dry-run]
// Builds a small fixture project (with the kind of noise real repos have: node_modules, a big lockfile, logs),
// then runs the same read-only prompts with `claude -p` in two arms and compares real cost, turns and tokens:
//   baseline = no template files
//   template = project generated by init.mjs (CLAUDE.md, rules, skills, agents, hooks, deny rules)
// Both arms load project settings only (--setting-sources project, no MCP), so user plugins/settings do not skew it.
// The same --model is forced on both arms, so the model_profile saving is NOT included. n is small: read the spread.
// Set CLAUDE_BIN if `claude` is not on PATH.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const arg = (n, d) => { const i = process.argv.indexOf(n); return i >= 0 && process.argv[i + 1] ? process.argv[i + 1] : d; };
const RUNS = Number(arg('--runs', 1));
const NTASKS = Number(arg('--tasks', 5));
const MODEL = arg('--model', 'sonnet');
const BUDGET = arg('--budget', '0.6');
const DRY = process.argv.includes('--dry-run');
const BIN = process.env.CLAUDE_BIN || 'claude';

const TASKS = [
  'Where is the user password hashed and compared? Answer in 3 lines.',
  'Orders sometimes show a wrong total. Find the cause in the code and explain it briefly. Do not edit files.',
  'What tests exist and how do I run them? Answer in 3 lines.',
  'Are there any errors or warnings in the application logs? Summarize in 3 lines.',
  'Which version of express is installed, and which other packages does the lockfile pin? Keep it short.',
].slice(0, NTASKS);

function write(f, s) { fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, s); }

function fixture(dir) {
  write(path.join(dir, 'package.json'), JSON.stringify({ name: 'shop-api', version: '1.0.0', scripts: { test: 'node --test' }, dependencies: { express: '^4.19.0' } }, null, 2) + '\n');
  write(path.join(dir, 'src/server.js'), "const express = require('express');\nconst auth = require('./auth');\nconst orders = require('./orders');\nconst app = express();\napp.use(express.json());\napp.post('/login', auth.login);\napp.get('/orders/:id', auth.require, orders.get);\napp.post('/orders', auth.require, orders.create);\napp.get('/health', (req, res) => res.json({ ok: true }));\nmodule.exports = app;\n");
  write(path.join(dir, 'src/auth.js'), "const crypto = require('crypto');\nconst users = new Map();\nfunction hash(pw, salt) { return crypto.scryptSync(pw, salt, 32).toString('hex'); }\nfunction login(req, res) {\n  const u = users.get(req.body.email);\n  if (!u || hash(req.body.password, u.salt) !== u.hash) return res.status(401).json({ error: 'bad credentials' });\n  res.json({ token: crypto.randomBytes(16).toString('hex') });\n}\nfunction require_(req, res, next) { if (!req.headers.authorization) return res.status(401).end(); next(); }\nmodule.exports = { login, require: require_, hash, users };\n");
  write(path.join(dir, 'src/orders.js'), "const store = new Map();\nfunction total(items, discount = 0) {\n  let sum = 0;\n  for (const it of items) sum += Math.round(it.price * it.qty); // rounds each line before the discount\n  return sum - Math.round(sum * discount);\n}\nfunction create(req, res) { const id = String(store.size + 1); store.set(id, { id, total: total(req.body.items, req.body.discount) }); res.status(201).json(store.get(id)); }\nfunction get(req, res) { const o = store.get(req.params.id); if (!o) return res.status(404).end(); res.json(o); }\nmodule.exports = { create, get, total };\n");
  write(path.join(dir, 'test/orders.test.js'), "const test = require('node:test');\nconst assert = require('node:assert');\nconst { total } = require('../src/orders');\ntest('total sums lines', () => assert.strictEqual(total([{ price: 10, qty: 2 }]), 20));\ntest('total applies discount', () => assert.strictEqual(total([{ price: 10, qty: 2 }], 0.1), 18));\n");
  // Noise a real repo has: dependency tree, a large lockfile, logs. Never relevant to these tasks.
  for (let i = 0; i < 40; i++) write(path.join(dir, `node_modules/pkg${i}/index.js`), `module.exports = ${JSON.stringify('x'.repeat(2000))};\n`);
  write(path.join(dir, 'package-lock.json'), JSON.stringify({ lockfileVersion: 3, packages: Object.fromEntries(Array.from({ length: 1500 }, (_, i) => [`node_modules/pkg${i}`, { version: '1.0.0', resolved: `https://registry.npmjs.org/pkg${i}/-/pkg${i}-1.0.0.tgz`, integrity: 'sha512-' + 'a'.repeat(86) }])) }, null, 2));
  write(path.join(dir, 'logs/app.log'), Array.from({ length: 3000 }, (_, i) => `2026-01-01T00:00:${i % 60} INFO request ${i} ok`).join('\n'));
  write(path.join(dir, '.gitignore'), 'node_modules/\nlogs/\n');
  spawnSync('git', ['init', '-q'], { cwd: dir });
}

function runClaude(dir, prompt) {
  const args = ['-p', prompt, '--output-format', 'json', '--model', MODEL, '--setting-sources', 'project', '--strict-mcp-config',
    '--no-session-persistence', '--max-budget-usd', BUDGET, '--allowed-tools', 'Read', 'Grep', 'Glob'];
  const r = spawnSync(BIN, args, { cwd: dir, encoding: 'utf8', timeout: 300000 });
  try { return JSON.parse(r.stdout); } catch { return { error: (r.stderr || r.stdout || 'no output').slice(0, 300) }; }
}

const base = fs.mkdtempSync(path.join(os.tmpdir(), 'bench-cost-'));
const arms = { baseline: path.join(base, 'baseline'), template: path.join(base, 'template') };
for (const d of Object.values(arms)) fixture(d);
write(path.join(arms.template, 'project.config.yml'), 'name: shop-api\ntype: api\nstack: [node, express]\npackage_manager: npm\ntest_command: "npm test"\nbranches: {working: dev, integration: "", production: main}\n');
const g = spawnSync(process.execPath, [path.join(HERE, 'init.mjs'), '--target', arms.template], { encoding: 'utf8' });
if (g.status !== 0) { console.error(g.stderr); process.exit(1); }

const plan = TASKS.length * RUNS * 2;
console.log(`Fixture in ${base}\n${plan} runs (${TASKS.length} tasks x ${RUNS} runs x 2 arms), model ${MODEL}, cap $${BUDGET}/run (worst case $${(plan * Number(BUDGET)).toFixed(2)}).`);
if (DRY) { console.log('--dry-run: nothing executed.'); fs.rmSync(base, { recursive: true, force: true }); process.exit(0); }

// Warm-up (not counted): the first request of each arm writes its prompt cache at a higher price; real sessions amortize that.
for (const arm of ['baseline', 'template']) { const j = runClaude(arms[arm], TASKS[0]); console.log(`  warm-up ${arm}: $${(j.total_cost_usd ?? 0).toFixed(4)} (not counted)`); }

const results = { baseline: [], template: [] };
for (let r = 0; r < RUNS; r++) {
  for (const [ti, prompt] of TASKS.entries()) {
    for (const arm of (r + ti) % 2 ? ['template', 'baseline'] : ['baseline', 'template']) { // alternate order so cache warmth is not biased
      const j = runClaude(arms[arm], prompt);
      if (j.error || j.is_error) { console.error(`  ${arm} task ${ti + 1} run ${r + 1}: FAILED ${j.error || j.result}`); continue; }
      const u = j.usage || {};
      const row = { task: ti + 1, cost: j.total_cost_usd ?? 0, turns: j.num_turns ?? 0, input: (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.cache_read_input_tokens || 0), output: u.output_tokens || 0 };
      results[arm].push(row);
      console.log(`  ${arm.padEnd(8)} task ${ti + 1} run ${r + 1}: $${row.cost.toFixed(4)}  ${row.turns} turns  in ${row.input}  out ${row.output}`);
    }
  }
}
fs.rmSync(base, { recursive: true, force: true });

console.log('\nper task (cost USD)       baseline   template     change');
for (let i = 1; i <= TASKS.length; i++) {
  const b = results.baseline.filter((x) => x.task === i), tt = results.template.filter((x) => x.task === i);
  if (!b.length || !tt.length) continue;
  const bc = b.reduce((n, x) => n + x.cost, 0) / b.length, tc = tt.reduce((n, x) => n + x.cost, 0) / tt.length;
  console.log(`task ${i} ${TASKS[i - 1].slice(0, 12).padEnd(14)}${bc.toFixed(4).padStart(10)}${tc.toFixed(4).padStart(11)}${(((tc - bc) / bc) * 100).toFixed(0).concat('%').padStart(11)}`);
}

const sum = (a, k) => a.reduce((n, x) => n + x[k], 0);
const avg = (a, k) => (a.length ? sum(a, k) / a.length : 0);
console.log('\nper-run average          baseline   template     change');
for (const [label, k, f] of [['cost (USD)', 'cost', (v) => v.toFixed(4)], ['turns', 'turns', (v) => v.toFixed(1)], ['input tokens (all)', 'input', (v) => Math.round(v)], ['output tokens', 'output', (v) => Math.round(v)]]) {
  const b = avg(results.baseline, k), t = avg(results.template, k);
  console.log(`${label.padEnd(22)}${String(f(b)).padStart(10)}${String(f(t)).padStart(11)}${(b ? `${(((t - b) / b) * 100).toFixed(0)}%` : 'n/a').padStart(11)}`);
}
console.log(`\nn = ${results.baseline.length} baseline / ${results.template.length} template runs. Small sample: differences under ~15% are within noise.`);
